function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function idx(h) { const o = {}; (h || []).forEach(function (k, i) { o[nz(k)] = i; }); return o; }
const v = $('GET pilot').first().json.valueRanges || [];
const st = (v[0] || {}).values || [], pipe = (v[1] || {}).values || [], inv = (v[2] || {}).values || [];
if (st.length < 40 || pipe.length < 500 || inv.length < 100) { throw new Error('ABORT short read'); }
const SH = idx(st[0]), PH = idx(pipe[0]), IH = idx(inv[0]);
const startups = {};
for (let r = 1; r < st.length; r++) { const row = st[r] || []; const n = s(row[SH.startup]); if (!n) { continue; }
  startups[nz(n)] = { n: n, active: s(row[SH.active]), stage: s(row[SH.stage]), raise: s(row[SH.raiseinrcr]), rev: s(row[SH.revenue]).replace(/\s+/g, ' ').slice(0, 70), sector: s(row[SH.sector]).slice(0, 60) }; }
const TARGET = ['PiperSireca', 'DSG Consumer Partners', 'Hem Angels', 'Vertex Ventures', 'Atomic Capital', 'Zeren Capital', 'Dexter Ventures', 'Equentis'];
const out = {};
TARGET.forEach(function (t) { out[t] = { investors_row: '', queued_live: {}, queued_live_total: 0, paused_or_dropped: 0, sent: 0, sent_no_response_followups_live: 0 }; });
for (let r = 1; r < inv.length; r++) { const row = inv[r] || []; const n = s(row[IH.investor]); const t = TARGET.find(function (x) { return nz(x) === nz(n); }); if (t) { out[t].investors_row = [s(row[IH.stage]), s(row[IH.chequeinrcr]), s(row[IH.sector]).slice(0, 90), 'dnc=' + s(row[IH.donotcontact])].join(' | '); } }
const used = {};
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || []; const iv = s(row[PH.investor]); const t = TARGET.find(function (x) { return nz(x) === nz(iv); }); if (!t) { continue; }
  const sent = /^yes$/i.test(s(row[PH.dealshared])); const paused = /^yes$/i.test(s(row[PH.pause])); const su = s(row[PH.startup]); const o = out[t];
  if (sent) { o.sent++; if (!paused && !s(row[PH.investorresponse]) && /follow/i.test(s(row[PH.nextaction]))) { o.sent_no_response_followups_live++; } }
  else if (paused) { o.paused_or_dropped++; }
  else { o.queued_live_total++; o.queued_live[su] = (o.queued_live[su] || 0) + 1; used[nz(su)] = 1; } }
Object.keys(out).forEach(function (t) { out[t].queued_live = Object.keys(out[t].queued_live).map(function (k) { return k + (out[t].queued_live[k] > 1 ? ' x' + out[t].queued_live[k] : ''); }); });
const revTable = Object.keys(used).map(function (k) { const x = startups[k]; return x ? [x.n, x.stage, x.raise, x.rev, x.sector] : [k, 'NOT IN STARTUPS']; });
return [{ json: { investors: out, startups_in_those_queues: revTable } }];
